"use client";
/* Drone, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Drone(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("drone"); }, []);
  return React.createElement("piix-pal", { "pal": "drone", ...piixAttrs(props) });
}

export default Drone;
